contracts/UMCBridgeHedera.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

/**
 * @title IUMCToken - Interface for the UMC token on Hedera
 */
interface IUMCToken {
    function burnFrom(address account, uint256 amount) external;
    function allowance(address owner, address spender) external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title UMCBridgeHedera - Burn side of the Hedera → Polygon bridge
 * @notice Users burn UMC on Hedera and provide a Polygon destination address.
 *         An off-chain relayer detects BridgeBurn events and mints on Polygon.
 *
 * @dev Security model:
 *   - Nonce-based replay protection (each burn has a unique nonce)
 *   - Minimum/maximum bridge amounts to prevent dust attacks and limit exposure
 *   - Daily volume cap to limit damage from relayer compromise
 *   - Pausable for emergencies
 *   - Fee mechanism for operational sustainability
 */
contract UMCBridgeHedera is
    Initializable,
    AccessControlUpgradeable,
    PausableUpgradeable,
    UUPSUpgradeable
{
    // =========================================================================
    // ROLES
    // =========================================================================

    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    // =========================================================================
    // STATE
    // =========================================================================

    /// @notice The UMC token contract on Hedera
    IUMCToken public umcToken;

    /// @notice Auto-incrementing nonce for each bridge request
    uint256 public bridgeNonce;

    /// @notice Minimum amount that can be bridged (in smallest unit)
    uint256 public minBridgeAmount;

    /// @notice Maximum amount per single bridge transaction
    uint256 public maxBridgeAmount;

    /// @notice Bridge fee in basis points (1 bp = 0.01%)
    uint256 public feeBasisPoints;

    /// @notice Address that receives collected fees
    address public feeRecipient;

    /// @notice Daily volume tracking
    uint256 public dailyVolume;
    uint256 public dailyVolumeLimit;
    uint256 public currentDay;

    /// @notice Mapping of nonce → whether the burn has been processed
    mapping(uint256 => bool) public processedNonces;

    /// @notice Mapping of nonce → burn details for verification
    mapping(uint256 => BridgeBurnRecord) public burnRecords;

    struct BridgeBurnRecord {
        address hederaSender;
        address polygonRecipient;
        uint256 amount;
        uint256 fee;
        uint256 netAmount;
        uint256 timestamp;
        bool exists;
    }

    // =========================================================================
    // EVENTS
    // =========================================================================

    /**
     * @notice Emitted when a user burns UMC to bridge to Polygon.
     *         The relayer watches for this event.
     */
    event BridgeBurn(
        uint256 indexed nonce,
        address indexed hederaSender,
        address indexed polygonRecipient,
        uint256 amount,
        uint256 fee,
        uint256 netAmount,
        uint256 timestamp
    );

    event BridgeConfigUpdated(
        uint256 minAmount,
        uint256 maxAmount,
        uint256 feeBps,
        uint256 dailyLimit
    );

    event FeeRecipientUpdated(address indexed newRecipient);

    // =========================================================================
    // ERRORS
    // =========================================================================

    error InvalidAddress();
    error InvalidAmount();
    error BelowMinimum(uint256 amount, uint256 minimum);
    error AboveMaximum(uint256 amount, uint256 maximum);
    error DailyLimitExceeded(uint256 requested, uint256 remaining);
    error InsufficientAllowance(uint256 required, uint256 allowed);
    error InsufficientBalance(uint256 required, uint256 available);
    error InvalidFee();

    // =========================================================================
    // INITIALIZER
    // =========================================================================

    /**
     * @param _umcToken Address of the UMC token contract on Hedera
     * @param _admin Admin address (should be multi-sig in production)
     * @param _feeRecipient Address to receive bridge fees
     * @param _minBridgeAmount Minimum bridge amount (e.g., 1 UMC = 1_000_000)
     * @param _maxBridgeAmount Maximum bridge amount per tx
     * @param _feeBasisPoints Fee in basis points (e.g., 25 = 0.25%)
     * @param _dailyVolumeLimit Maximum daily bridge volume
     */
    function initialize(
        address _umcToken,
        address _admin,
        address _feeRecipient,
        uint256 _minBridgeAmount,
        uint256 _maxBridgeAmount,
        uint256 _feeBasisPoints,
        uint256 _dailyVolumeLimit
    ) public initializer {
        if (_umcToken == address(0)) revert InvalidAddress();
        if (_admin == address(0)) revert InvalidAddress();
        if (_feeRecipient == address(0)) revert InvalidAddress();
        if (_feeBasisPoints > 1000) revert InvalidFee(); // Max 10%

        __AccessControl_init();
        __Pausable_init();

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(OPERATOR_ROLE, _admin);
        _grantRole(UPGRADER_ROLE, _admin);

        umcToken = IUMCToken(_umcToken);
        feeRecipient = _feeRecipient;
        minBridgeAmount = _minBridgeAmount;
        maxBridgeAmount = _maxBridgeAmount;
        feeBasisPoints = _feeBasisPoints;
        dailyVolumeLimit = _dailyVolumeLimit;
        currentDay = block.timestamp / 1 days;
    }

    // =========================================================================
    // BRIDGE: BURN ON HEDERA
    // =========================================================================

    /**
     * @notice Burn UMC on Hedera to receive UMC on Polygon.
     * @dev User must first approve this contract to spend their UMC.
     *      The relayer detects the BridgeBurn event and mints on Polygon.
     * @param polygonRecipient The user's address on Polygon
     * @param amount The gross amount of UMC to bridge (fee deducted from this)
     */
    function bridgeToPolygon(
        address polygonRecipient,
        uint256 amount
    ) external whenNotPaused {
        if (polygonRecipient == address(0)) revert InvalidAddress();
        if (amount == 0) revert InvalidAmount();
        if (amount < minBridgeAmount) revert BelowMinimum(amount, minBridgeAmount);
        if (amount > maxBridgeAmount) revert AboveMaximum(amount, maxBridgeAmount);

        // Reset daily volume if new day
        uint256 today = block.timestamp / 1 days;
        if (today > currentDay) {
            currentDay = today;
            dailyVolume = 0;
        }

        // Check daily limit
        if (dailyVolume + amount > dailyVolumeLimit) {
            revert DailyLimitExceeded(amount, dailyVolumeLimit - dailyVolume);
        }

        // Verify allowance and balance
        uint256 allowed = umcToken.allowance(msg.sender, address(this));
        if (allowed < amount) revert InsufficientAllowance(amount, allowed);
        uint256 balance = umcToken.balanceOf(msg.sender);
        if (balance < amount) revert InsufficientBalance(amount, balance);

        // Calculate fee
        uint256 fee = (amount * feeBasisPoints) / 10_000;
        uint256 netAmount = amount - fee;

        // Burn the full amount from the user
        // Fee portion is also burned — the fee recipient is compensated
        // off-chain or via a separate mechanism to keep this simple
        umcToken.burnFrom(msg.sender, amount);

        // Update daily volume
        dailyVolume += amount;

        // Record the burn
        uint256 nonce = bridgeNonce++;
        processedNonces[nonce] = true;
        burnRecords[nonce] = BridgeBurnRecord({
            hederaSender: msg.sender,
            polygonRecipient: polygonRecipient,
            amount: amount,
            fee: fee,
            netAmount: netAmount,
            timestamp: block.timestamp,
            exists: true
        });

        emit BridgeBurn(
            nonce,
            msg.sender,
            polygonRecipient,
            amount,
            fee,
            netAmount,
            block.timestamp
        );
    }

    // =========================================================================
    // VIEWS
    // =========================================================================

    /**
     * @notice Calculate the net amount and fee for a given bridge amount.
     */
    function calculateBridgeAmount(
        uint256 grossAmount
    ) external view returns (uint256 netAmount, uint256 fee) {
        fee = (grossAmount * feeBasisPoints) / 10_000;
        netAmount = grossAmount - fee;
    }

    /**
     * @notice Get remaining daily bridge volume.
     */
    function remainingDailyVolume() external view returns (uint256) {
        uint256 today = block.timestamp / 1 days;
        if (today > currentDay) return dailyVolumeLimit;
        return dailyVolumeLimit > dailyVolume
            ? dailyVolumeLimit - dailyVolume
            : 0;
    }

    /**
     * @notice Get burn record by nonce.
     */
    function getBurnRecord(
        uint256 nonce
    ) external view returns (BridgeBurnRecord memory) {
        return burnRecords[nonce];
    }

    // =========================================================================
    // ADMIN
    // =========================================================================

    function updateBridgeConfig(
        uint256 _minBridgeAmount,
        uint256 _maxBridgeAmount,
        uint256 _feeBasisPoints,
        uint256 _dailyVolumeLimit
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_feeBasisPoints > 1000) revert InvalidFee();
        minBridgeAmount = _minBridgeAmount;
        maxBridgeAmount = _maxBridgeAmount;
        feeBasisPoints = _feeBasisPoints;
        dailyVolumeLimit = _dailyVolumeLimit;
        emit BridgeConfigUpdated(
            _minBridgeAmount,
            _maxBridgeAmount,
            _feeBasisPoints,
            _dailyVolumeLimit
        );
    }

    function setFeeRecipient(
        address _feeRecipient
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_feeRecipient == address(0)) revert InvalidAddress();
        feeRecipient = _feeRecipient;
        emit FeeRecipientUpdated(_feeRecipient);
    }

    function pause() external onlyRole(OPERATOR_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(OPERATOR_ROLE) {
        _unpause();
    }

    function _authorizeUpgrade(
        address
    ) internal override onlyRole(UPGRADER_ROLE) {}
}

contracts/UMCBridgePolygon.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

interface IUMCTokenPolygon {
    function mint(address to, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title UMCBridgePolygon - Mint side of the Hedera to Polygon bridge
 * @notice Receives signed EIP-712 attestations from relayers to mint UMC on Polygon.
 *
 * @dev Security:
 *   - EIP-712 typed signatures prevent replay across chains/contracts
 *   - Nonce replay protection (each Hedera burn nonce mints exactly once)
 *   - Value-tiered signatures (more sigs for large amounts)
 *   - Time-bounded claims (attestations expire)
 *   - Pausable for emergencies
 */
contract UMCBridgePolygon is
    Initializable,
    AccessControlUpgradeable,
    PausableUpgradeable,
    EIP712Upgradeable,
    UUPSUpgradeable
{
    using ECDSA for bytes32;

    bytes32 public constant RELAYER_ROLE = keccak256("RELAYER_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    bytes32 public constant MINT_TYPEHASH = keccak256(
        "MintAttestation(uint256 hederaNonce,address polygonRecipient,uint256 amount,uint256 deadline)"
    );

    IUMCTokenPolygon public umcToken;
    mapping(uint256 => bool) public claimedNonces;

    uint256 public requiredSignatures;
    uint256 public highValueThreshold;
    uint256 public highValueRequiredSignatures;
    uint256 public claimWindow;
    uint256 public totalBridgedAmount;

    struct ClaimRecord {
        address recipient;
        uint256 amount;
        uint256 hederaNonce;
        uint256 claimedAt;
    }
    mapping(uint256 => ClaimRecord) public claims;

    event BridgeMint(uint256 indexed hederaNonce, address indexed polygonRecipient, uint256 amount, uint256 timestamp);
    event ClaimWindowUpdated(uint256 newWindow);
    event SignatureConfigUpdated(uint256 required, uint256 hvThreshold, uint256 hvRequired);

    error InvalidAddress();
    error InvalidAmount();
    error NonceAlreadyClaimed(uint256 nonce);
    error AttestationExpired(uint256 deadline, uint256 currentTime);
    error InsufficientSignatures(uint256 provided, uint256 required);
    error InvalidSignature();
    error DuplicateSigner();

    function initialize(
        address _umcToken, address _admin, address _relayer, uint256 _claimWindow
    ) public initializer {
        if (_umcToken == address(0)) revert InvalidAddress();
        if (_admin == address(0)) revert InvalidAddress();
        if (_relayer == address(0)) revert InvalidAddress();

        __AccessControl_init();
        __Pausable_init();
        __EIP712_init("UMCBridge", "1");

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(RELAYER_ROLE, _relayer);
        _grantRole(OPERATOR_ROLE, _admin);
        _grantRole(UPGRADER_ROLE, _admin);

        umcToken = IUMCTokenPolygon(_umcToken);
        requiredSignatures = 1;
        highValueThreshold = 1_000_000 * 1e6;
        highValueRequiredSignatures = 2;
        claimWindow = _claimWindow;
    }

    /**
     * @notice Claim bridged UMC using relayer-signed EIP-712 attestation(s).
     * @param hederaNonce Burn nonce from Hedera bridge contract
     * @param polygonRecipient Recipient address (must match signed data)
     * @param amount Net amount to mint (must match signed data)
     * @param deadline Expiry timestamp (must match signed data)
     * @param signatures Array of EIP-712 relayer signatures
     */
    function claimMint(
        uint256 hederaNonce,
        address polygonRecipient,
        uint256 amount,
        uint256 deadline,
        bytes[] calldata signatures
    ) external whenNotPaused {
        if (polygonRecipient == address(0)) revert InvalidAddress();
        if (amount == 0) revert InvalidAmount();
        if (claimedNonces[hederaNonce]) revert NonceAlreadyClaimed(hederaNonce);
        if (block.timestamp > deadline) revert AttestationExpired(deadline, block.timestamp);

        uint256 sigsRequired = amount >= highValueThreshold
            ? highValueRequiredSignatures : requiredSignatures;

        if (signatures.length < sigsRequired) {
            revert InsufficientSignatures(signatures.length, sigsRequired);
        }

        bytes32 structHash = keccak256(
            abi.encode(MINT_TYPEHASH, hederaNonce, polygonRecipient, amount, deadline)
        );
        bytes32 digest = _hashTypedDataV4(structHash);

        address[] memory signers = new address[](signatures.length);
        for (uint256 i = 0; i < signatures.length; i++) {
            address signer = ECDSA.recover(digest, signatures[i]);
            if (!hasRole(RELAYER_ROLE, signer)) revert InvalidSignature();
            for (uint256 j = 0; j < i; j++) {
                if (signers[j] == signer) revert DuplicateSigner();
            }
            signers[i] = signer;
        }

        claimedNonces[hederaNonce] = true;
        claims[hederaNonce] = ClaimRecord({
            recipient: polygonRecipient,
            amount: amount,
            hederaNonce: hederaNonce,
            claimedAt: block.timestamp
        });
        totalBridgedAmount += amount;

        umcToken.mint(polygonRecipient, amount);
        emit BridgeMint(hederaNonce, polygonRecipient, amount, block.timestamp);
    }

    function isNonceClaimed(uint256 nonce) external view returns (bool) { return claimedNonces[nonce]; }
    function getDomainSeparator() external view returns (bytes32) { return _domainSeparatorV4(); }

    function computeMintDigest(
        uint256 hederaNonce, address polygonRecipient, uint256 amount, uint256 deadline
    ) external view returns (bytes32) {
        return _hashTypedDataV4(
            keccak256(abi.encode(MINT_TYPEHASH, hederaNonce, polygonRecipient, amount, deadline))
        );
    }

    function setClaimWindow(uint256 _claimWindow) external onlyRole(DEFAULT_ADMIN_ROLE) {
        claimWindow = _claimWindow;
        emit ClaimWindowUpdated(_claimWindow);
    }

    function setSignatureConfig(
        uint256 _required, uint256 _hvThreshold, uint256 _hvRequired
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        requiredSignatures = _required;
        highValueThreshold = _hvThreshold;
        highValueRequiredSignatures = _hvRequired;
        emit SignatureConfigUpdated(_required, _hvThreshold, _hvRequired);
    }

    function pause() external onlyRole(OPERATOR_ROLE) { _pause(); }
    function unpause() external onlyRole(OPERATOR_ROLE) { _unpause(); }
    function _authorizeUpgrade(address) internal override onlyRole(UPGRADER_ROLE) {}
}

contracts/UMCToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20BurnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

/**
 * @title UMCToken - USD-Pegged Stablecoin on Hedera
 * @author Fatai / Ikoyi Closet
 * @notice A secure, upgradeable ERC-20 stablecoin pegged 1:1 to the US Dollar.
 *         Deployed on Hedera via the Hedera Smart Contract Service (EVM-compatible).
 *
 * @dev Security features:
 *   - Role-based access control (Admin, Minter, Pauser, Blacklister, Upgrader)
 *   - Pausable transfers for emergency scenarios
 *   - Address blacklisting for regulatory compliance
 *   - Supply cap enforcement
 *   - UUPS upgradeable proxy pattern
 *   - Reentrancy-safe by design (no external calls in state-changing functions)
 *
 * @dev Stablecoin mechanics:
 *   - 6 decimals (standard for USD stablecoins, matching USDC/USDT)
 *   - Mint/burn controlled by authorized minters (backed by reserves)
 *   - Configurable supply cap
 */
contract UMCToken is
    Initializable,
    ERC20Upgradeable,
    ERC20BurnableUpgradeable,
    ERC20PausableUpgradeable,
    AccessControlUpgradeable,
    UUPSUpgradeable
{
    // =========================================================================
    // ROLES
    // =========================================================================

    /// @notice Role that can mint new tokens (reserve-backed minting)
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    /// @notice Role that can pause/unpause all transfers
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /// @notice Role that can blacklist/unblacklist addresses
    bytes32 public constant BLACKLISTER_ROLE = keccak256("BLACKLISTER_ROLE");

    /// @notice Role that can authorize contract upgrades
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    // =========================================================================
    // STATE
    // =========================================================================

    /// @notice Maximum total supply that can ever be minted (in smallest unit)
    uint256 public supplyCap;

    /// @notice Mapping of blacklisted addresses (frozen for compliance)
    mapping(address => bool) private _blacklisted;

    /// @notice Tracks per-minter allowances for granular supply control
    mapping(address => uint256) public minterAllowance;

    // =========================================================================
    // EVENTS
    // =========================================================================

    event Blacklisted(address indexed account);
    event UnBlacklisted(address indexed account);
    event SupplyCapUpdated(uint256 oldCap, uint256 newCap);
    event MinterAllowanceSet(address indexed minter, uint256 allowance);
    event Mint(address indexed minter, address indexed to, uint256 amount);
    event Burn(address indexed burner, uint256 amount);

    // =========================================================================
    // ERRORS
    // =========================================================================

    error AccountBlacklisted(address account);
    error SupplyCapExceeded(uint256 requested, uint256 available);
    error MinterAllowanceExceeded(uint256 requested, uint256 allowance);
    error InvalidAddress();
    error InvalidAmount();
    error InvalidCap();

    // =========================================================================
    // INITIALIZER (replaces constructor for upgradeable pattern)
    // =========================================================================

    /**
     * @notice Initializes the UMC stablecoin contract.
     * @param defaultAdmin Address that receives DEFAULT_ADMIN_ROLE
     * @param initialSupplyCap Maximum supply cap (in smallest unit, 6 decimals)
     */
    function initialize(
        address defaultAdmin,
        uint256 initialSupplyCap
    ) public initializer {
        if (defaultAdmin == address(0)) revert InvalidAddress();
        if (initialSupplyCap == 0) revert InvalidCap();

        __ERC20_init("UMC Stablecoin", "UMC");
        __ERC20Burnable_init();
        __ERC20Pausable_init();
        __AccessControl_init();

        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);
        _grantRole(MINTER_ROLE, defaultAdmin);
        _grantRole(PAUSER_ROLE, defaultAdmin);
        _grantRole(BLACKLISTER_ROLE, defaultAdmin);
        _grantRole(UPGRADER_ROLE, defaultAdmin);

        supplyCap = initialSupplyCap;
    }

    // =========================================================================
    // ERC-20 OVERRIDES
    // =========================================================================

    /**
     * @notice UMC uses 6 decimals (USD stablecoin standard).
     */
    function decimals() public pure override returns (uint8) {
        return 6;
    }

    // =========================================================================
    // MINTING
    // =========================================================================

    /**
     * @notice Mint new UMC tokens. Only callable by MINTER_ROLE.
     * @dev Enforces both the global supply cap and per-minter allowance.
     *      Each mint should correspond to verified USD reserves.
     * @param to Recipient address
     * @param amount Amount to mint (in smallest unit)
     */
    function mint(address to, uint256 amount) external onlyRole(MINTER_ROLE) {
        if (to == address(0)) revert InvalidAddress();
        if (amount == 0) revert InvalidAmount();
        if (_blacklisted[to]) revert AccountBlacklisted(to);

        // Enforce global supply cap
        uint256 newSupply = totalSupply() + amount;
        if (newSupply > supplyCap) {
            revert SupplyCapExceeded(amount, supplyCap - totalSupply());
        }

        // Enforce per-minter allowance
        uint256 allowed = minterAllowance[msg.sender];
        if (amount > allowed) {
            revert MinterAllowanceExceeded(amount, allowed);
        }
        unchecked {
            minterAllowance[msg.sender] = allowed - amount;
        }

        _mint(to, amount);
        emit Mint(msg.sender, to, amount);
    }

    /**
     * @notice Burn UMC tokens from caller's balance (redeeming for USD).
     * @param amount Amount to burn
     */
    function burn(uint256 amount) public override {
        if (amount == 0) revert InvalidAmount();
        super.burn(amount);
        emit Burn(msg.sender, amount);
    }

    /**
     * @notice Set a minter's allowance (how much they can mint).
     * @param minter Address of the minter
     * @param allowance Maximum mintable amount
     */
    function setMinterAllowance(
        address minter,
        uint256 allowance
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (minter == address(0)) revert InvalidAddress();
        if (!hasRole(MINTER_ROLE, minter)) {
            revert InvalidAddress(); // Must be a minter
        }
        minterAllowance[minter] = allowance;
        emit MinterAllowanceSet(minter, allowance);
    }

    // =========================================================================
    // BLACKLISTING (Regulatory Compliance)
    // =========================================================================

    /**
     * @notice Blacklist an address, preventing it from sending or receiving UMC.
     * @param account Address to blacklist
     */
    function blacklist(
        address account
    ) external onlyRole(BLACKLISTER_ROLE) {
        if (account == address(0)) revert InvalidAddress();
        _blacklisted[account] = true;
        emit Blacklisted(account);
    }

    /**
     * @notice Remove an address from the blacklist.
     * @param account Address to unblacklist
     */
    function unBlacklist(
        address account
    ) external onlyRole(BLACKLISTER_ROLE) {
        if (account == address(0)) revert InvalidAddress();
        _blacklisted[account] = false;
        emit UnBlacklisted(account);
    }

    /**
     * @notice Check if an address is blacklisted.
     * @param account Address to check
     * @return True if the address is blacklisted
     */
    function isBlacklisted(address account) external view returns (bool) {
        return _blacklisted[account];
    }

    // =========================================================================
    // PAUSE / UNPAUSE (Emergency Controls)
    // =========================================================================

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    // =========================================================================
    // SUPPLY CAP MANAGEMENT
    // =========================================================================

    /**
     * @notice Update the maximum supply cap.
     * @dev New cap must be >= current total supply.
     * @param newCap New maximum supply cap
     */
    function setSupplyCap(
        uint256 newCap
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (newCap < totalSupply()) revert InvalidCap();
        uint256 oldCap = supplyCap;
        supplyCap = newCap;
        emit SupplyCapUpdated(oldCap, newCap);
    }

    // =========================================================================
    // INTERNAL OVERRIDES
    // =========================================================================

    /**
     * @dev Hook that enforces blacklist checks on every transfer.
     */
    function _update(
        address from,
        address to,
        uint256 value
    ) internal override(ERC20Upgradeable, ERC20PausableUpgradeable) {
        // Skip blacklist check for mint (from == 0) and burn (to == 0)
        if (from != address(0) && _blacklisted[from]) {
            revert AccountBlacklisted(from);
        }
        if (to != address(0) && _blacklisted[to]) {
            revert AccountBlacklisted(to);
        }
        super._update(from, to, value);
    }

    /**
     * @dev Restrict upgrades to UPGRADER_ROLE.
     */
    function _authorizeUpgrade(
        address newImplementation
    ) internal override onlyRole(UPGRADER_ROLE) {}
}

